// ErrorCode names an error the server has its own copy of.
func ErrorCode(err error) string {
	switch {
	case errors.Is(err, wittyplay.ErrEncrypted3DS):
		return "wittyplay.ErrEncrypted3DS"
	case errors.Is(err, wittyplay.ErrPlayBinWithCue):
		return "wittyplay.ErrPlayBinWithCue"
	case errors.Is(err, wittyplay.ErrPlayLoneBin):
		return "wittyplay.ErrPlayLoneBin"
	case errors.Is(err, patch.ErrSource):
		return "patch.ErrSource"
	case errors.Is(err, stream.ErrBusy):
		return "stream.ErrBusy"
	case errors.Is(err, stream.ErrGPUBusy):
		return "stream.ErrGPUBusy"
	case errors.Is(err, stream.ErrNoDevice):
		return "stream.ErrNoDevice"
	case errors.Is(err, stream.ErrNoSlot):
		return "stream.ErrNoSlot"
	case errors.Is(err, stream.ErrReplaced):
		return "stream.ErrReplaced"
	case errors.Is(err, stream.ErrRunnerDied):
		return "stream.ErrRunnerDied"
	case errors.Is(err, stream.ErrSaveFull):
		return "stream.ErrSaveFull"
	case errors.Is(err, stream.ErrStopped):
		return "stream.ErrStopped"
	}
	return ""
}
